class TestRuntimeIntegration:
    """End-to-end flow with a mock runtime implementation."""

    def test_full_lifecycle(self):
        """Complete build -> run -> stop -> cleanup cycle."""
        class MockRuntime(ContainerRuntime):
            def __init__(self):
                self.build_called = False
                self.run_called = False
                self.stop_called = False
                self.cleanup_called = False

            def build(self, context: str, tag: str) -> ContainerResult:
                self.build_called = True
                return ContainerResult(0, f"Built {tag}", "", 100.0, "mock")

            def run(self, image: str, command: Optional[List[str]] = None) -> ContainerResult:
                self.run_called = True
                return ContainerResult(0, f"Ran {image}", "", 50.0, "mock")

            def stop(self, container_id: str) -> ContainerResult:
                self.stop_called = True
                return ContainerResult(0, f"Stopped {container_id}", "", 10.0, "mock")

            def cleanup(self) -> None:
                self.cleanup_called = True

        runtime = MockRuntime()

        # Build
        build_result = runtime.build("/ctx", "myapp:latest")
        assert build_result.exit_code == 0
        assert "myapp:latest" in build_result.stdout
        assert runtime.build_called

        # Run
        run_result = runtime.run("myapp:latest", ["--port", "8080"])
        assert run_result.exit_code == 0
        assert "myapp:latest" in run_result.stdout
        assert runtime.run_called

        # Stop
        stop_result = runtime.stop("container-123")
        assert stop_result.exit_code == 0
        assert "container-123" in stop_result.stdout
        assert runtime.stop_called

        # Cleanup
        runtime.cleanup()
        assert runtime.cleanup_called

    def test_error_propagation(self):
        """Runtime failures must be captured in ContainerResult."""
        class FailingRuntime(ContainerRuntime):
            def build(self, context: str, tag: str) -> ContainerResult:
                return ContainerResult(1, "", "Build failed", 5.0, "mock")

            def run(self, image: str, command: Optional[List[str]] = None) -> ContainerResult:
                return ContainerResult(1, "", "Run failed", 5.0, "mock")

            def stop(self, container_id: str) -> ContainerResult:
                return ContainerResult(1, "", "Stop failed", 5.0, "mock")

            def cleanup(self) -> None:
                pass

        runtime = FailingRuntime()
        result = runtime.build("/ctx", "tag")
        assert result.exit_code == 1
        assert "Build failed" in result.stderr
        assert result.duration_ms == 5.0


