class TestPerformanceSmoke:
    """Quick performance sanity checks."""

    def test_bulk_creation(self):
        """Creating 10,000 ContainerResult instances must be fast."""
        import time

        start = time.perf_counter()
        for i in range(10000):
            ContainerResult(
                exit_code=i % 256,
                stdout=f"output-{i}",
                stderr="",
                duration_ms=float(i),
                runtime_used="docker",
            )
        elapsed = time.perf_counter() - start
        assert elapsed < 2.0, f"Bulk creation took {elapsed:.2f}s"

    def test_bulk_asdict(self):
        """asdict() on 10,000 instances must be fast."""
        import time

        results = [
            ContainerResult(
                exit_code=i % 256,
                stdout=f"output-{i}",
                stderr="",
                duration_ms=float(i),
                runtime_used="docker",
            )
            for i in range(10000)
        ]

        start = time.perf_counter()
        for r in results:
            asdict(r)
        elapsed = time.perf_counter() - start
        assert elapsed < 2.0, f"Bulk asdict took {elapsed:.2f}s"